<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); $industry=isset($_GET['industry'])?sanitize_text_field(wp_unslash($_GET['industry'])):''; $visa_only=!empty($_GET['visa_sponsored']); $terms=get_terms(array('taxonomy'=>'nvconsult_industry','hide_empty'=>true)); ?>
<main class="archive-shell"><section class="archive-hero"><h1><?php post_type_archive_title(); ?></h1><p><?php esc_html_e( 'Find international job opportunities aligned with your skills and relocation goals.', 'nvconsult-theme-v2' ); ?></p></section><section class="section" style="padding-top:24px;"><form class="filter-bar" method="get"><select name="industry"><option value=""><?php esc_html_e( 'All industries', 'nvconsult-theme-v2' ); ?></option><?php foreach($terms as $term): ?><option value="<?php echo esc_attr( $term->slug ); ?>" <?php selected($industry,$term->slug); ?>><?php echo esc_html( $term->name ); ?></option><?php endforeach; ?></select><label><input type="checkbox" name="visa_sponsored" value="1" <?php checked($visa_only); ?>> <?php esc_html_e( 'Visa sponsored only', 'nvconsult-theme-v2' ); ?></label><button class="btn-primary" type="submit"><?php esc_html_e( 'Filter Jobs', 'nvconsult-theme-v2' ); ?></button></form><div class="archive-grid"><?php if(have_posts()): while(have_posts()): the_post(); if($industry&&!has_term($industry,'nvconsult_industry',get_the_ID())){continue;} if($visa_only&&'1'!==get_post_meta(get_the_ID(),'_nvconsult_visa_sponsored',true)){continue;} ?><article class="archive-card content-card"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( get_post_meta( get_the_ID(), '_nvconsult_location', true ) ); ?></p><p><strong><?php echo esc_html( get_post_meta( get_the_ID(), '_nvconsult_salary_range', true ) ); ?></strong></p><?php if('1'===get_post_meta(get_the_ID(),'_nvconsult_visa_sponsored',true)): ?><span class="visa-badge"><?php esc_html_e( 'Visa Sponsored', 'nvconsult-theme-v2' ); ?></span><?php endif; ?><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 22 ) ); ?></p></article><?php endwhile; else: ?><div class="placeholder-message"><p><?php esc_html_e( 'No jobs found.', 'nvconsult-theme-v2' ); ?></p></div><?php endif; ?></div></section></main>
<?php get_footer(); ?>
